window.HAATHI_STORIES=[{"id": "ganesha_moon", "title": "Ganesha and the Moon", "group": "Puranas and folk", "age": 3, "source": "Traditional Ganesha tale, told at Ganesh Chaturthi", "series": null, "ep": null, "moral": "Do not laugh when someone falls. Help them up instead.", "talk": "What can we do when a friend falls down?", "pages": [{"t": "It was Ganesha's birthday, and everyone gave him sweet modaks. Ganesha ate one, and two, and ten, and twenty!", "s": "home|🐘@50,62,34;🍡@22,78,12;🍡@78,78,12;👑@50,38,10"}, {"t": "Late at night, Ganesha rode home on his little mouse friend. His tummy was very, very full.", "s": "forestN+moon+stars|🐘@48,58,30;🐭@52,80,14"}, {"t": "A snake crossed the path. The mouse jumped with fright, and Ganesha tumbled down. Plop! Out rolled all the modaks.", "s": "forestN+moon|🐘@40,64,28;🐭@70,80,12;🐍@80,66,14;🍡@20,84,8;🍡@30,88,8"}, {"t": "High in the sky, the Moon saw it all and laughed and laughed. Ha ha ha!", "s": "skyN+stars|🌝@50,40,40"}, {"t": "Ganesha felt sad. 'It is not kind to laugh when someone falls,' he said.", "s": "forestN+moon+stars|🐘@50,62,32;💧@60,48,6"}, {"t": "Ganesha said, 'Because you laughed, you will lose your shine.' The Moon felt sorry and begged, 'Please forgive me.' Ganesha was kind, and said, 'You will shrink a little each night, and then grow full again.'", "s": "skyN+stars|🌝@62,34,30;🐘@30,70,26;🙏@62,58,8"}, {"t": "And that is why the Moon grows and shrinks every month. On Ganesh Chaturthi, many people still remember this story and do not look at the Moon.", "s": "skyN+stars|🌙@30,36,14;🌓@50,36,14;🌕@70,36,14;🐘@50,74,22"}]}, {"id": "ganesha_race", "title": "Ganesha's Race Around the World", "group": "Puranas and folk", "age": 3, "source": "Traditional tale (the 'fruit of wisdom' story)", "series": null, "ep": null, "moral": "Our family is our whole world. Thinking well can be better than rushing.", "talk": "Who is your whole world? Why?", "pages": [{"t": "Shiva and Parvati had two sons: Kartikeya and little Ganesha. One day they held up a magic mango.", "s": "mountain+sun|🧔@30,60,22;👸@48,60,22;🥭@64,40,12"}, {"t": "'Whoever goes around the whole world three times, first, will get this mango,' said Parvati.", "s": "mountain+sun|👸@40,60,26;🥭@60,40,14;🐘@75,72,18;🧒@85,70,16"}, {"t": "Kartikeya jumped on his peacock and zoom! He flew away over seas and mountains.", "s": "sea+sun+clouds|🦚@55,45,30;🧒@55,32,14"}, {"t": "Ganesha only had a little mouse. He sat and thought, and thought.", "s": "mountain|🐘@50,60,30;🐭@70,80,12;💭@68,32,12"}, {"t": "Then he walked slowly around his mother and father, one, two, three times, with folded hands.", "s": "mountain+sun|🧔@40,58,22;👸@58,58,22;🐘@80,74,18;🙏@80,56,8"}, {"t": "'Why did you do that?' they asked. Ganesha said, 'You are my whole world.' Parvati hugged him and gave him the sweet mango.", "s": "mountain+sun|👸@42,58,26;🐘@62,66,24;🥭@62,40,10;💛@52,40,8"}]}, {"id": "krishna_butter", "title": "Little Krishna and the Butter Pot", "group": "Puranas and folk", "age": 3, "source": "Bhagavata Purana, Book 10", "series": null, "ep": null, "moral": "It is better to tell the truth. Mothers love us even when we are naughty.", "talk": "Have you ever done something naughty? What did you say?", "pages": [{"t": "In the village of Gokul lived a naughty little boy called Krishna. He loved butter more than anything.", "s": "village+sun|🧒@50,62,28;🪶@56,40,8;🧈@72,76,10"}, {"t": "Mother Yashoda hung the butter pot high up, where little hands could not reach it.", "s": "home|👩@36,60,28;🏺@66,26,14"}, {"t": "Krishna called his friends. One stood, one climbed up, and Krishna climbed on top! He reached the pot. Yum!", "s": "home|🧒@60,74,18;🧒@60,54,18;🧒@60,34,18;🏺@60,16,12"}, {"t": "They shared the butter with the monkeys too. Everyone had butter on their faces and laughed.", "s": "home|🧒@34,64,22;🐒@64,66,20;🧈@50,82,10;😄@80,40,10"}, {"t": "Yashoda came home. 'Krishna! Did you eat the butter?' Krishna wiped his mouth and said, 'Not me, Ma!'", "s": "home|👩@34,58,28;🧒@68,66,22;🪶@72,46,6"}, {"t": "Yashoda laughed and hugged her butter-thief. No matter how naughty he was, she loved him so much.", "s": "home+sun|👩@44,58,30;🧒@60,66,20;💛@52,34,10"}]}, {"id": "govardhan", "title": "Krishna Lifts the Mountain", "group": "Puranas and folk", "age": 5, "source": "Bhagavata Purana, Book 10", "series": null, "ep": null, "moral": "Kindness and courage protect the people we love. Be thankful to nature that cares for us.", "talk": "What in nature are you thankful for?", "pages": [{"t": "The people of Gokul prayed every year to Indra, the god of rain. But little Krishna said, 'Let us thank Govardhan hill instead. It gives our cows grass and water.'", "s": "village+sun|🧒@40,62,24;🐄@70,70,22;⛰️@50,26,30"}, {"t": "Indra was angry. He sent dark clouds, thunder and heavy rain. The rain fell for days and the river rose.", "s": "village+rain+clouds|⚡@50,18,16;🐄@40,72,18;🧑@66,72,16"}, {"t": "The people and cows were cold and scared. 'Krishna, help us!' they cried.", "s": "village+rain+clouds|🧑@30,68,16;👩@48,68,16;🐄@68,72,18;🧒@85,70,14"}, {"t": "Krishna smiled. He went to Govardhan hill and lifted the whole mountain on his little finger, like an umbrella!", "s": "mountain+rain+clouds|⛰️@50,36,44;🧒@50,78,18;☝️@50,64,6"}, {"t": "Everyone came under the mountain with their cows and calves. They were dry and safe for seven days.", "s": "mountain+rain|⛰️@50,30,48;🐄@28,78,16;🧑@46,80,12;👩@62,80,12;🐄@78,78,16"}, {"t": "At last Indra understood. He stopped the rain and said sorry. Krishna put the mountain back, and everyone danced in the sunshine.", "s": "village+sun|🧒@50,62,22;🌈@50,20,40;🐄@20,72,16;🧑@78,70,14"}]}, {"id": "hanuman_sun", "title": "Baby Hanuman and the Sun", "group": "Puranas and folk", "age": 3, "source": "Valmiki's Ramayana, Kishkindha Kanda", "series": null, "ep": null, "moral": "Be curious, but also be careful. Use your strength to help others.", "talk": "If you could fly, where would you go?", "pages": [{"t": "Baby Hanuman woke up very hungry. He looked out and saw something big, round and orange in the sky.", "s": "forest+sun|🐒@40,70,26"}, {"t": "'A big ripe mango!' he thought. And whoosh! Baby Hanuman jumped high up into the sky.", "s": "forest+clouds|🐒@46,40,22;☀️@80,18,22"}, {"t": "He flew past birds and clouds, higher and higher, towards the shiny Sun.", "s": "skyN+clouds|🐒@40,56,20;🐦@20,40,8;☀️@78,24,28"}, {"t": "Indra, king of the gods, was worried, and threw his thunderbolt. It hit the baby's chin, and Hanuman fell gently down to a mountain.", "s": "mountain+clouds|⚡@50,24,14;🐒@50,66,16"}, {"t": "His father Vayu, the wind god, was so upset that he stopped all the wind. The gods quickly healed the baby and gave him great blessings. Because his chin, his hanu, was hurt, he was called Hanuman.", "s": "forest+sun|🌬️@30,30,14;🐒@50,66,22;✨@70,36,12"}, {"t": "When Hanuman grew up, he became strong, brave and kind, and he always used his strength to help others.", "s": "mountain+sun|🐒@50,58,34;🏔️@80,40,16"}]}, {"id": "squirrel_rama", "title": "The Squirrel who Helped Rama", "group": "Puranas and folk", "age": 3, "source": "Folk tradition (not in Valmiki's Ramayana)", "series": null, "ep": null, "moral": "No help is too small. Everyone can do their part.", "talk": "What small thing can you do to help at home?", "pages": [{"t": "Prince Rama needed to cross the big sea to bring Sita home. The monkeys began to build a bridge of stones.", "s": "sea+sun|🤴@24,62,22;🐒@50,70,18;🐒@70,72,18;🪨@60,84,10"}, {"t": "Big monkeys carried big rocks. Splash! Splash! The bridge grew longer and longer.", "s": "sea+sun|🐒@36,56,22;🪨@36,40,14;🐒@68,62,22;🪨@68,46,12"}, {"t": "A tiny squirrel wanted to help too. She rolled in the sand and shook it off on the bridge, again and again.", "s": "sea+sun|🐿️@50,76,16;🪨@30,84,10;🪨@70,84,10"}, {"t": "The big monkeys laughed. 'What can a tiny squirrel do?' The squirrel felt small and sad.", "s": "sea|🐒@30,58,24;🐒@70,58,24;🐿️@50,80,12"}, {"t": "But Rama picked her up gently. 'Every bit of help matters,' he said. 'Your sand fills the gaps between the stones.'", "s": "sea+sun|🤴@50,56,30;🐿️@56,40,10;💛@70,30,8"}, {"t": "He stroked her back softly with three fingers. And that is why, they say, squirrels have three stripes on their backs today.", "s": "forest+sun|🐿️@50,60,30"}]}, {"id": "dhruva", "title": "Dhruva, the Boy who Became a Star", "group": "Puranas and folk", "age": 5, "source": "Bhagavata Purana, Book 4", "series": null, "ep": null, "moral": "With patience and a steady heart, you can reach your dreams.", "talk": "Can you find a bright star in the sky tonight?", "pages": [{"t": "Long ago, there was a five-year-old prince called Dhruva. He wanted to sit on the lap of his father, King Uttanapada.", "s": "palace|🤴@50,56,28;🧒@76,72,16"}, {"t": "But his stepmother Suruchi pulled him away. 'You cannot sit here,' she said. Dhruva ran to his mother, crying.", "s": "palace|👸@34,56,26;🧒@68,70,16;💧@72,56,5"}, {"t": "His mother Suniti hugged him. 'Pray to Lord Vishnu, my son. He loves everyone.'", "s": "home|👩@44,58,28;🧒@64,68,18;🪔@24,78,10"}, {"t": "On the way to the forest, he met the sage Narada, who taught him a prayer: Om Namo Bhagavate Vasudevaya.", "s": "forest+sun|🧔@36,60,22;🧒@62,68,16;🪕@26,46,8"}, {"t": "In the Madhuvan forest, Dhruva sat very still and prayed, through sunny days and cold nights, without giving up.", "s": "forestN+moon+stars|🧒@50,70,20;🙏@50,56,6"}, {"t": "Lord Vishnu was moved by his patience. He appeared and said, 'Dhruva, you will shine forever.'", "s": "skyN+stars|✨@50,30,30;🧒@50,72,18"}, {"t": "Dhruva became the Pole Star, the star that never moves. Even today, travellers look up at Dhruva to find their way home.", "s": "skyN+stars+moon|⭐@50,22,14;🧭@30,76,12;🛶@70,80,14"}]}, {"id": "sudama", "title": "Krishna and His Friend Sudama", "group": "Puranas and folk", "age": 5, "source": "Bhagavata Purana, Book 10", "series": null, "ep": null, "moral": "True friends love you for who you are, not for what you give.", "talk": "Who is your best friend? What do you like about them?", "pages": [{"t": "When they were boys, Krishna and Sudama studied together at the same school in the forest. They were best friends.", "s": "forest+sun|🧒@40,64,20;🧒@60,64,20;📚@50,80,8"}, {"t": "Krishna grew up to be a king in a golden palace. Sudama stayed very poor and had little to eat.", "s": "village|🧔@50,62,26;🛖@24,60,18"}, {"t": "Sudama's wife said, 'Go and meet your friend Krishna.' Sudama had no gift, only a small bundle of beaten rice, poha.", "s": "village|🧔@40,62,24;👩@64,62,22;🍚@52,82,8"}, {"t": "When Krishna saw Sudama at the gate, he ran out barefoot and hugged him with tears of joy.", "s": "palace+sun|🧒@40,62,24;🧔@62,62,24;💛@51,40,8"}, {"t": "Sudama felt shy about his small gift. But Krishna ate the poha happily. 'This is the tastiest gift I have ever had!'", "s": "palace|🧒@40,64,22;🧔@64,64,22;🍚@52,80,8;😋@40,44,8"}, {"t": "When Sudama went home, he found his hut had become a beautiful house. True friends care about love, not about gifts.", "s": "village+sun|🏡@50,52,34;🧔@30,78,14;👩@70,78,14"}]}, {"id": "monkey_croc", "title": "The Monkey and the Crocodile", "group": "Panchatantra", "age": 5, "source": "", "series": null, "ep": null, "moral": "Keep calm and think when you are in trouble. Choose friends who are true.", "talk": "How did the monkey stay safe?", "pages": [{"t": "A clever monkey lived in a jamun tree by the river. Every day he shared sweet jamuns with his friend, the crocodile.", "s": "river+sun|🌳@70,40,40;🐒@66,32,12;🐊@34,80,24"}, {"t": "The crocodile took some jamuns home to his wife. 'If the fruit is so sweet,' she said, 'the monkey's heart must be sweeter! Bring it to me.'", "s": "river|🐊@34,76,24;🐊@64,78,22;🫐@50,60,8"}, {"t": "The crocodile said to the monkey, 'Come home for dinner, my friend. Sit on my back.' The monkey happily jumped on.", "s": "river+sun|🐊@50,76,30;🐒@50,62,14"}, {"t": "In the middle of the river, the crocodile said, 'Sorry, friend. My wife wants to eat your heart!'", "s": "river|🐊@50,76,30;🐒@50,62,14;😮@62,48,8"}, {"t": "The monkey thought quickly. 'Oh! I left my heart in the jamun tree. Take me back and I will get it.'", "s": "river|🐊@50,76,30;🐒@50,62,14;💭@68,40,10;🌳@86,38,14"}, {"t": "The silly crocodile swam back. The monkey leapt up the tree and laughed. 'A heart lives inside the body! Our friendship is over.'", "s": "river+sun|🌳@66,40,40;🐒@66,28,12;🐊@30,82,22"}]}, {"id": "thirsty_crow", "title": "The Thirsty Crow", "group": "Aesop", "age": 3, "source": "", "series": null, "ep": null, "moral": "Where there is a will, there is a way. Think and keep trying.", "talk": "What would you do if you could not reach something?", "pages": [{"t": "It was a hot, hot summer day. A crow flew and flew, looking for water.", "s": "field+sun|🐦@50,40,18"}, {"t": "At last he found a pot with a little water at the very bottom. But his beak could not reach it.", "s": "garden+sun|🏺@50,70,24;🐦@50,44,14"}, {"t": "The crow did not give up. He looked around and saw some small pebbles.", "s": "garden+sun|🐦@40,56,14;🪨@64,82,6;🪨@72,84,6;🪨@58,86,6"}, {"t": "One by one, he dropped the pebbles into the pot. Plink, plink, plink!", "s": "garden+sun|🏺@50,70,24;🐦@50,40,14;🪨@50,52,5"}, {"t": "The water rose higher and higher, until it reached the top.", "s": "garden+sun|🏺@50,70,24;💧@50,52,8;🐦@60,40,14"}, {"t": "The crow drank the cool water and flew away happily. Caw, caw, caw!", "s": "field+sun|🐦@60,34,18;😊@40,24,8"}]}, {"id": "lion_mouse", "title": "The Lion and the Mouse", "group": "Aesop", "age": 3, "source": "", "series": null, "ep": null, "moral": "Be kind to everyone. Even little friends can help in big ways.", "talk": "When did a small friend help you?", "pages": [{"t": "A big lion was sleeping in the forest. A tiny mouse ran over his nose by mistake.", "s": "forest+sun|🦁@50,66,36;🐭@54,52,8"}, {"t": "The lion woke up and caught the mouse with his paw. 'Grrr! I will eat you!'", "s": "forest|🦁@44,62,38;🐭@70,66,8"}, {"t": "'Please let me go,' squeaked the mouse. 'One day I will help you.' The lion laughed, but he let the mouse go.", "s": "forest|🦁@40,62,34;🐭@72,80,10"}, {"t": "Days later, the lion was caught in a hunter's net. He roared and roared, but he could not get out.", "s": "forest|🦁@50,62,34;🕸️@50,62,40"}, {"t": "The little mouse heard him. She came running and nibbled the ropes, nibble, nibble, until the net broke.", "s": "forest|🦁@50,60,32;🐭@66,78,10;🕸️@50,62,30"}, {"t": "The lion was free! 'Thank you, little friend,' he said. From then on, the lion and the mouse were best friends.", "s": "forest+sun|🦁@40,62,32;🐭@68,74,12;💛@54,40,8"}]}, {"id": "tortoise_hare", "title": "The Tortoise and the Hare", "group": "Aesop", "age": 3, "source": "", "series": null, "ep": null, "moral": "Slow and steady wins the race. Do not show off.", "talk": "Is it good to show off? Why?", "pages": [{"t": "A rabbit loved to show off. 'I am the fastest! Nobody can beat me.' The slow tortoise said, 'Let us have a race.'", "s": "field+sun|🐇@36,66,20;🐢@66,74,20"}, {"t": "Ready, steady, go! The rabbit ran off zoom, and the tortoise walked step by step.", "s": "field+sun|🐇@72,64,18;🐢@24,76,16;🏁@92,62,10"}, {"t": "The rabbit was far ahead. 'I have so much time,' he said, and lay down under a tree for a nap.", "s": "field+sun|🌳@60,40,30;🐇@60,72,16;💤@70,58,8"}, {"t": "The tortoise did not stop. Step, step, step. He walked past the sleeping rabbit.", "s": "field|🐇@40,74,16;💤@48,62,6;🐢@68,76,16"}, {"t": "The rabbit woke up and ran very fast, but it was too late. The tortoise crossed the finish line!", "s": "field+sun|🐢@80,74,18;🏁@90,62,10;🐇@36,66,16"}, {"t": "Everyone cheered for the tortoise. Slow and steady wins the race.", "s": "field+sun|🐢@50,68,24;🏆@50,40,12;🎉@76,30,10"}]}, {"id": "blue_jackal", "title": "The Blue Jackal", "group": "Panchatantra", "age": 5, "source": "", "series": null, "ep": null, "moral": "Be yourself. Pretending to be someone else does not last.", "talk": "What do you like about being you?", "pages": [{"t": "One night, a hungry jackal ran into a village. The dogs chased him, and he fell into a big tub of blue dye.", "s": "village+moon|🦊@50,64,22;🐕@80,66,16;🛁@40,82,18"}, {"t": "When he climbed out, he was bright blue from nose to tail! He ran back to the forest.", "s": "forestN+moon|🦊@50,64,26;🔵@64,48,8"}, {"t": "The animals had never seen a blue animal. 'Who are you?' they asked, scared.", "s": "forest|🦊@50,62,22;🐇@20,74,12;🦌@80,66,16;🐘@30,58,18"}, {"t": "The jackal had an idea. 'I am your new king, sent from the sky!' The animals believed him and brought him food.", "s": "forest+sun|🦊@50,56,22;👑@50,40,8;🦁@24,70,18;🐅@78,70,18"}, {"t": "One night, the other jackals howled at the moon. The blue jackal could not help it. He howled too: Owooo!", "s": "forestN+moon+stars|🦊@50,62,24;🌝@76,20,14"}, {"t": "Now everyone knew he was just a jackal. He had to run away. Pretending to be someone else never works for long.", "s": "forestN+moon|🦊@76,70,16;🦁@36,62,24"}]}, {"id": "talkative_tortoise", "title": "The Talkative Tortoise", "group": "Panchatantra", "age": 5, "source": "", "series": null, "ep": null, "moral": "Know when to talk and when to stay quiet.", "talk": "When is it important to stay quiet and listen?", "pages": [{"t": "A tortoise lived in a pond with two swans. The tortoise loved to talk, talk, talk all day.", "s": "pond+sun|🐢@50,74,18;🦢@26,66,16;🦢@74,66,16"}, {"t": "One summer the pond dried up. 'Come with us to a big lake,' said the swans.", "s": "pond|🐢@50,78,16;🦢@30,62,16;🦢@70,62,16;☀️@84,16,14"}, {"t": "They held a stick in their beaks. 'Hold the middle with your mouth, and do not talk, whatever happens!'", "s": "pond+sun|🦢@30,52,16;🦢@70,52,16;🥢@50,52,30;🐢@50,64,14"}, {"t": "Up, up they flew over the village. Children pointed and shouted, 'Look, a flying tortoise!'", "s": "village+sun+clouds|🦢@34,30,14;🦢@66,30,14;🐢@50,40,10;🧒@40,82,10;🧒@60,82,10"}, {"t": "The tortoise wanted to answer. He opened his mouth, 'Yes, I am fly...' and down he fell! Splash, into a small pond.", "s": "village|🐢@50,70,14;💦@50,82,14;🦢@40,20,12;🦢@60,20,12"}, {"t": "He was safe, but very wet. The swans came down and he said, 'Next time, I will know when to be quiet.'", "s": "pond+sun|🐢@50,76,18;🦢@30,64,16;🦢@70,64,16"}]}, {"id": "elephant_mice", "title": "The Elephants and the Mice", "group": "Panchatantra", "age": 3, "source": "", "series": null, "ep": null, "moral": "Be kind to all, big or small. Friends help each other.", "talk": "How can you be kind to someone smaller than you?", "pages": [{"t": "Many mice lived happily in an old, quiet town. One day, a big herd of elephants walked through to reach the lake.", "s": "village+sun|🐘@40,58,26;🐘@70,60,24;🐭@20,84,8"}, {"t": "Stomp, stomp! The elephants squashed many mouse holes. The mouse king said, 'Dear elephants, please take another path.'", "s": "village|🐘@60,58,30;🐭@26,80,12;👑@26,70,5"}, {"t": "The kind elephant king said, 'We are sorry. We will go another way.' The mice thanked them.", "s": "forest+sun|🐘@40,58,32;🐭@72,80,12;💛@58,36,8"}, {"t": "Later, hunters trapped the elephants with big ropes and nets. The elephants could not move!", "s": "forest|🐘@40,60,26;🐘@68,62,24;🕸️@54,60,48"}, {"t": "One elephant called for the mice. Hundreds of mice came running and nibbled all the ropes.", "s": "forest|🐘@50,58,30;🐭@26,84,8;🐭@40,86,8;🐭@60,86,8;🐭@74,84,8"}, {"t": "Snap! The elephants were free. 'Thank you, little friends!' Being kind to others comes back to you.", "s": "forest+sun|🐘@36,58,26;🐘@64,58,26;🐭@50,84,10;🎉@50,30,10"}]}, {"id": "ant_dove", "title": "The Ant and the Dove", "group": "Aesop", "age": 3, "source": "", "series": null, "ep": null, "moral": "Help others, and they will help you too.", "talk": "Who helped you today?", "pages": [{"t": "A little ant went to the river to drink water. A wave came, and splash! The ant fell into the river.", "s": "river+sun|🐜@50,74,10;💦@50,80,12"}, {"t": "A dove sitting on a tree saw her. Quickly, she dropped a leaf into the water.", "s": "river+sun|🕊️@70,30,16;🍃@50,70,10;🐜@50,76,8"}, {"t": "The ant climbed onto the leaf and floated safely to the shore. 'Thank you, kind dove!'", "s": "river+sun|🍃@30,80,10;🐜@30,76,8;🕊️@70,32,14"}, {"t": "A few days later, a hunter came with a net to catch the dove.", "s": "forest|🧑@30,60,22;🕸️@40,50,12;🕊️@70,30,14"}, {"t": "The ant saw him and bit his foot, hard! 'Ouch!' The hunter jumped, and the dove heard him and flew away.", "s": "forest|🧑@40,60,24;🐜@40,86,8;🕊️@80,18,12"}, {"t": "The dove and the ant were safe. One good turn deserves another.", "s": "forest+sun|🕊️@40,40,18;🐜@60,76,10;💛@50,56,8"}]}, {"id": "woodcutter", "title": "The Honest Woodcutter", "group": "Folk tale", "age": 5, "source": "", "series": null, "ep": null, "moral": "Honesty is the best policy.", "talk": "Why did the goddess give him all three axes?", "pages": [{"t": "A poor woodcutter was cutting wood by a river. His hand slipped, and his iron axe fell into the deep water.", "s": "river+sun|🧔@40,60,24;🪓@60,80,8;🌳@80,40,20"}, {"t": "He sat down and cried. 'That axe is all I have.' Suddenly, a kind river goddess rose from the water.", "s": "river|🧔@30,62,22;🧜‍♀️@64,62,22;✨@64,40,10"}, {"t": "She dived down and came up with a golden axe. 'Is this yours?' 'No,' said the woodcutter. 'Mine was not gold.'", "s": "river|🧜‍♀️@60,62,22;🪓@60,44,10;🟡@68,40,5;🧔@28,62,20"}, {"t": "She brought up a silver axe. 'Is this yours?' 'No,' he said again. 'Mine was iron.'", "s": "river|🧜‍♀️@60,62,22;🪓@60,44,10;⚪@68,40,5;🧔@28,62,20"}, {"t": "Then she brought up his old iron axe. 'Yes! That is mine!' he said happily.", "s": "river+sun|🧜‍♀️@60,62,22;🪓@60,44,10;🧔@28,62,20;😊@28,44,8"}, {"t": "'You are honest,' said the goddess, and she gave him all three axes. Honesty is the best treasure.", "s": "river+sun|🧔@44,62,24;🪓@64,56,8;🪓@72,56,8;🪓@80,56,8;✨@60,30,10"}]}, {"id": "haathi_dark", "title": "Haathi is Scared of the Dark", "group": "Feelings", "age": 3, "source": "", "series": null, "ep": null, "moral": "It is okay to feel scared. Slow breaths and a hug help.", "talk": "What helps you feel safe at night?", "pages": [{"t": "It was bedtime in the Mango Forest. Mama switched off the light, and little Haathi pulled his blanket up high.", "s": "homeN+moon|🐘@50,66,30;🛏️@50,80,30"}, {"t": "'Mama, the dark is scary. What if there is a monster?' said Haathi in a tiny voice.", "s": "homeN|🐘@50,66,28;😟@64,46,8"}, {"t": "Mama came back and sat with him. 'It is okay to feel scared. Let us look at the dark together.'", "s": "homeN+moon|🐘@40,60,32;🐘@62,70,20"}, {"t": "That shape was not a monster. It was only his coat on a hook. And that sound? Only the wind singing.", "s": "homeN+moon|🧥@28,40,14;🌬️@74,30,12;🐘@54,72,18"}, {"t": "Mama gave him his teddy and a tiny night light. 'Take three slow breaths. In... and out.'", "s": "homeN|🐘@50,68,24;🧸@68,76,10;🪔@26,76,8"}, {"t": "Haathi breathed slowly. The dark felt soft and quiet now, like a big warm hug. Goodnight, Haathi.", "s": "homeN+moon+stars|🐘@50,70,26;💤@66,52,8"}]}, {"id": "grumpy_cloud", "title": "The Grumpy Cloud", "group": "Feelings", "age": 3, "source": "", "series": null, "ep": null, "moral": "When you feel angry, take a deep breath and use your words.", "talk": "What do you do when you feel angry?", "pages": [{"t": "There was once a little cloud called Kalu. One morning he woke up grumpy. Nobody wanted to play with him!", "s": "field+clouds|☁️@50,30,30;😠@50,30,8"}, {"t": "Kalu felt hot and stormy inside. Rumble, rumble went his tummy, and boom! A thunder came out.", "s": "field+clouds|⛈️@50,30,32;⚡@60,50,10"}, {"t": "The birds flew away and the children ran inside. Now Kalu felt sad and alone.", "s": "village+rain|🌧️@50,26,28;🐦@80,20,8;🏠@30,70,16"}, {"t": "The wise old Sun peeped out. 'Kalu, when you feel stormy, take a deep breath and tell someone how you feel.'", "s": "field|☀️@76,22,22;☁️@40,32,22"}, {"t": "Kalu took a big breath, whoosh! 'I felt left out,' he said softly. The birds came back. 'Come, play with us!'", "s": "field+sun|☁️@40,30,24;🐦@60,26,8;🐦@70,34,8"}, {"t": "Kalu gave the fields a gentle rain, and a rainbow came out to play. Feelings pass, like clouds in the sky.", "s": "field+sun|🌈@50,24,50;☁️@24,26,16;🌻@30,82,10;🌻@70,82,10"}]}, {"id": "two_mangoes", "title": "Two Mangoes and One Friend", "group": "Feelings", "age": 3, "source": "", "series": null, "ep": null, "moral": "Sharing makes everyone happy, including you.", "talk": "What did you share today?", "pages": [{"t": "Chintu found two big, juicy mangoes under the tree. 'Both are mine!' he said.", "s": "garden+sun|🧒@40,64,24;🥭@64,78,10;🥭@74,78,10"}, {"t": "His friend Pinky sat nearby with an empty plate. She looked hungry and sad.", "s": "garden+sun|👧@60,64,24;🍽️@60,82,10"}, {"t": "Chintu ate one mango, but it did not taste so sweet when his friend was sad.", "s": "garden|🧒@40,64,24;🥭@46,78,10;👧@74,66,18"}, {"t": "He thought for a moment. Then he walked over and gave Pinky the other mango.", "s": "garden+sun|🧒@40,66,22;🥭@52,64,10;👧@64,66,22"}, {"t": "Pinky smiled a big smile. 'Thank you, Chintu!' They ate their mangoes together, laughing, juice dripping everywhere.", "s": "garden+sun|🧒@38,64,22;👧@62,64,22;🥭@50,82,8;😄@50,40,8"}, {"t": "Chintu learned something. Sharing made his heart feel full and happy.", "s": "garden+sun|🧒@44,64,24;👧@60,64,22;💛@52,36,10"}]}, {"id": "sorry_sparrow", "title": "Sorry, Little Sparrow", "group": "Feelings", "age": 3, "source": "", "series": null, "ep": null, "moral": "Saying sorry and helping to fix things makes friendships stronger.", "talk": "When did you last say sorry? How did it feel?", "pages": [{"t": "Gola the puppy loved to run. One day he ran so fast that he knocked over Chiku the sparrow's nest.", "s": "garden+sun|🐕@40,72,22;🪹@66,64,12;🐦@70,40,10"}, {"t": "Chiku cried, 'My home!' Gola wanted to run away and hide.", "s": "garden|🐦@66,38,12;💧@72,30,4;🐕@26,72,18"}, {"t": "But his tummy felt funny. He knew what he had to do.", "s": "garden|🐕@50,70,24;💭@64,48,10"}, {"t": "He walked back and said, 'I am sorry, Chiku. I was running too fast. Can I help you fix your nest?'", "s": "garden+sun|🐕@40,72,20;🐦@64,52,12;🪹@64,70,12"}, {"t": "Together they found twigs, grass and soft leaves. Chiku built, and Gola fetched.", "s": "garden+sun|🐕@30,74,18;🐦@60,48,10;🌿@46,84,8;🍃@62,84,8"}, {"t": "The new nest was even cosier than before. 'Thank you, Gola. You are a good friend.'", "s": "garden+sun|🪹@60,60,14;🐦@60,48,10;🐕@34,72,18;💛@46,40,8"}]}, {"id": "first_day", "title": "Chintu's First Day at School", "group": "Feelings", "age": 3, "source": "", "series": null, "ep": null, "moral": "New places can feel scary at first. A brave hello can make a new friend.", "talk": "How do you make a new friend?", "pages": [{"t": "Chintu held Mama's hand tightly at the school gate. His tummy felt full of butterflies.", "s": "school+sun|🧒@40,66,22;👩@60,62,28;🦋@40,46,6"}, {"t": "'What if nobody plays with me?' he whispered. Mama smiled. 'Say hello, and see what happens.'", "s": "school|🧒@40,66,22;👩@60,60,28"}, {"t": "Inside, there were colours, blocks and a big smiling teacher. 'Welcome, Chintu!'", "s": "school+sun|👩‍🏫@60,60,26;🧒@32,68,18;🧱@74,82,8"}, {"t": "A girl with a red bow was building a tower. Chintu said a tiny 'Hello.' 'Hello! Want to build with me?'", "s": "school|👧@60,66,20;🧒@36,68,18;🧱@50,82,10"}, {"t": "They built the tallest tower in the class. Then they ate lunch and sang songs together.", "s": "school+sun|🧒@36,68,18;👧@62,68,18;🗼@50,52,14;🎵@50,30,8"}, {"t": "When Mama came, Chintu ran to her. 'Mama, I have a new friend! Can I come again tomorrow?'", "s": "school+sun|🧒@40,68,20;👩@62,60,26;😄@40,48,8"}]}, {"id": "missing_nani", "title": "Missing Nani", "group": "Feelings", "age": 3, "source": "", "series": null, "ep": null, "moral": "It is okay to miss people. Love stays with us even when they are far.", "talk": "Who do you miss? What could you make for them?", "pages": [{"t": "Pinky's Nani had gone back to her village far away. Pinky missed her soft hugs and her stories.", "s": "homeN|👧@50,66,24;💧@58,52,4"}, {"t": "'I miss Nani,' Pinky told Papa. 'My heart feels heavy.'", "s": "home|👧@36,66,20;👨@62,60,26"}, {"t": "Papa hugged her. 'Missing someone means you love them a lot. Shall we make something for Nani?'", "s": "home|👨@46,60,28;👧@62,68,18;💛@54,36,8"}, {"t": "Pinky drew a picture of Nani and herself under the mango tree, with a big yellow sun.", "s": "home+sun|👧@40,68,18;🖍️@60,82,8;🖼️@64,56,16"}, {"t": "Then they called Nani on the phone. 'Hello, my little sunshine!' said Nani, smiling on the screen.", "s": "home|👧@40,68,18;📱@60,58,14;👵@60,56,8"}, {"t": "Pinky showed her the drawing. 'Next holidays, we will sit under that mango tree together,' said Nani. Pinky slept with a smile.", "s": "homeN+moon+stars|👧@50,72,22;💤@64,56,8"}]}, {"id": "birbal_khichdi", "title": "Birbal's Khichdi", "group": "Clever and funny", "age": 5, "source": "", "series": null, "ep": null, "moral": "Be fair to everyone. A clever idea can show the truth.", "talk": "Why did Birbal hang the pot so high?", "pages": [{"t": "One cold winter, King Akbar said, 'If anyone stands in the freezing lake all night, I will give them a big prize.'", "s": "court|🤴@50,54,28;👳@76,66,18"}, {"t": "A poor man stood in the icy water all night. In the morning, he came for his prize.", "s": "pond+moon|🧑@50,66,20;🥶@50,46,8"}, {"t": "'How did you stay warm?' asked Akbar. 'There was a lamp far away in the palace. I looked at it all night,' said the man.", "s": "court|🤴@40,56,26;🧑@70,66,18;🪔@84,40,8"}, {"t": "'Then the lamp kept you warm! No prize,' said Akbar. The poor man went away sad. Birbal said nothing.", "s": "court|🤴@40,56,26;🧑@78,70,14;👳@60,66,18"}, {"t": "Next day, Birbal invited the king for lunch. He hung a pot of khichdi high on a tree, far above a tiny fire.", "s": "garden|🌳@60,34,36;🍲@60,30,10;🔥@60,84,8;👳@30,66,20"}, {"t": "'Birbal, it will never cook!' laughed Akbar. 'Why not, Your Majesty? If a far-away lamp can warm a man, my fire can cook the khichdi!'", "s": "garden|🤴@30,62,24;👳@64,64,20;🍲@64,30,8;🔥@64,84,6"}, {"t": "Akbar understood. He called the poor man back and gave him his prize. Everyone laughed at Birbal's clever lesson.", "s": "court+sun|🤴@40,56,26;🧑@66,66,18;🎁@66,48,8;👳@84,66,14"}]}, {"id": "tenali_thieves", "title": "Tenali Raman and the Thieves", "group": "Clever and funny", "age": 5, "source": "", "series": null, "ep": null, "moral": "Stay calm and think. A clever mind can solve big problems.", "talk": "How did Tenali get his garden watered?", "pages": [{"t": "One night, Tenali Raman heard whispers outside his house. Two thieves were hiding behind the bushes!", "s": "villageN+moon|🏠@50,52,30;🦹@20,74,14;🦹@80,74,14;👨@50,56,8"}, {"t": "Tenali said loudly to his wife, 'Thieves are about! Let us put our gold in this box and hide it in the well.'", "s": "homeN|👨@40,62,24;👩@62,62,22;📦@50,84,10"}, {"t": "He filled the box with stones and threw it into the well. Splash!", "s": "villageN+moon|👨@36,62,20;📦@60,72,10;🪣@62,60,8"}, {"t": "The thieves rushed to the well and started pulling out water, bucket after bucket, all night long.", "s": "villageN+moon|🦹@40,66,16;🦹@64,66,16;🪣@52,52,8;💦@30,84,10;💦@74,84,10"}, {"t": "The water flowed into Tenali's garden and watered all his plants. In the morning, they found only stones!", "s": "garden+sun|🦹@40,64,16;🦹@60,64,16;🪨@50,82,8;🌻@20,80,10;🌻@84,80,10"}, {"t": "Tenali stepped out and smiled. 'Thank you for watering my garden!' The thieves ran away and never came back.", "s": "garden+sun|👨@44,62,22;🌻@20,80,10;🌻@80,80,10;🦹@90,70,10"}]}, {"id": "birbal_line", "title": "Birbal and the Line", "group": "Clever and funny", "age": 5, "source": "", "series": null, "ep": null, "moral": "There is often more than one way to solve a problem.", "talk": "Can you think of another clever way?", "pages": [{"t": "One day, King Akbar drew a line on the floor of his court. 'Who can make this line shorter without rubbing any of it out?'", "s": "court|🤴@40,54,26;➖@64,80,20"}, {"t": "The ministers scratched their heads. 'How can a line get shorter without rubbing it out?'", "s": "court|🧔@30,64,18;🧑@50,64,18;🧓@70,64,18;❓@50,42,8"}, {"t": "Then Birbal stepped forward with a smile. He took the chalk.", "s": "court|👳@50,60,24;🖍️@66,60,8"}, {"t": "Next to the king's line, Birbal drew a much longer line.", "s": "court|👳@30,60,20;➖@60,76,14;➖@60,86,30"}, {"t": "'Now look, Your Majesty. Your line is the shorter one!' Akbar laughed and clapped. 'Well done, Birbal!'", "s": "court+sun|🤴@40,54,26;👳@70,62,20;👏@56,40,8"}]}, {"id": "goodnight_forest", "title": "Goodnight, Mango Forest", "group": "Sleepy", "age": 3, "source": "", "series": null, "ep": null, "moral": "", "talk": "Who will you say goodnight to tonight?", "pages": [{"t": "The sun is going down in the Mango Forest. The sky turns orange, then pink, then purple.", "s": "forest+sun+clouds|🐘@50,68,24;🦜@28,38,9;🐒@76,44,10"}, {"t": "Goodnight, birds, in your cosy nests. Goodnight, parrots, tucked in your tree.", "s": "forestN+moon|🪹@40,44,12;🦜@64,40,12"}, {"t": "Goodnight, cows, in the quiet barn. Goodnight, little calf, next to your mama.", "s": "villageN+moon|🐄@40,66,24;🐄@64,72,14"}, {"t": "Goodnight, fish, in the sleepy river. Goodnight, frog, on your lily pad.", "s": "riverN+moon|🐟@40,76,12;🐸@66,70,12"}, {"t": "Goodnight, moon, so round and bright. Goodnight, stars, twinkling light.", "s": "skyN+stars|🌕@50,36,26;⭐@24,24,6;⭐@76,20,6"}, {"t": "And goodnight to you, little one. Close your eyes, and dream sweet dreams. Haathi says goodnight.", "s": "homeN+moon+stars|🐘@50,68,28;💤@66,52,8"}]}, {"id": "counting_stars", "title": "Counting Stars with Haathi", "group": "Sleepy", "age": 3, "source": "", "series": null, "ep": null, "moral": "", "talk": "How many stars can you count before you fall asleep?", "pages": [{"t": "Haathi lay on the soft grass and looked up at the night sky. So many stars!", "s": "skyN+stars|🐘@50,80,26"}, {"t": "'Let us count them slowly,' said Haathi. One star... two stars... three stars.", "s": "skyN|⭐@30,30,8;⭐@50,22,8;⭐@70,30,8;🐘@50,80,22"}, {"t": "Four stars, five stars. A sleepy owl said, 'Hoo, hoo. Goodnight.'", "s": "skyN+stars|🦉@24,52,12;🐘@54,80,22"}, {"t": "Six stars, seven stars. Haathi's eyes felt heavy. His breathing got slow and soft.", "s": "skyN+stars+moon|🐘@50,80,22;💤@64,64,6"}, {"t": "Eight... nine... ten. The stars twinkled a lullaby, very, very quietly.", "s": "skyN+stars+moon|🐘@50,82,22;💤@64,66,8"}, {"t": "Haathi was fast asleep. Now you count the stars too, slowly, and drift into sweet dreams.", "s": "skyN+stars+moon|🐘@50,82,24;💤@66,66,10"}]}, {"id": "ram1", "title": "The Birth of Rama", "group": "Ramayana", "age": 3, "source": "Valmiki's Ramayana, Bala Kanda", "series": "Ramayana", "ep": 1, "moral": "Prayers, patience and love fill a family with joy.", "talk": "Do you have a brother, sister or cousin you love?", "pages": [{"t": "Long ago, in the beautiful city of Ayodhya, lived a good king called Dasharatha. He had three queens, Kausalya, Kaikeyi and Sumitra, but no children, and he felt sad.", "s": "palace+sun|🤴@50,60,28;👑@50,38,8"}, {"t": "The wise sages said, 'Let us pray with a great fire ceremony, a yajna.' The whole kingdom prayed together.", "s": "palace|🔥@50,74,16;🧔@26,66,18;🤴@74,64,20"}, {"t": "From the sacred fire rose a shining being, holding a golden bowl of sweet kheer. 'Give this to your queens,' he said.", "s": "palace|🔥@50,80,14;✨@50,40,26;🥣@50,58,10"}, {"t": "The king shared the kheer with his three queens. Soon, four baby boys were born!", "s": "palace+sun|👸@24,62,18;👸@50,62,18;👸@76,62,18;👶@50,84,10"}, {"t": "Kausalya's son was Rama. Kaikeyi's son was Bharata. And Sumitra had twins, Lakshmana and Shatrughna.", "s": "palace+sun|👶@20,70,14;👶@40,70,14;👶@60,70,14;👶@80,70,14"}, {"t": "The four brothers grew up loving each other. Lakshmana always stayed close to Rama, like his shadow.", "s": "garden+sun|🧒@40,64,22;🧒@58,66,18;🏹@28,80,8"}, {"t": "Rama grew up kind, brave and truthful. Everyone in Ayodhya loved him.", "s": "village+sun|🤴@50,60,28;🧑@20,72,12;👩@80,72,12"}]}, {"id": "ram2", "title": "Rama and the Sage Vishwamitra", "group": "Ramayana", "age": 3, "source": "Valmiki's Ramayana, Bala Kanda", "series": "Ramayana", "ep": 2, "moral": "The strong should protect the good and the weak.", "talk": "Who do you help and protect?", "pages": [{"t": "One day, the great sage Vishwamitra came to King Dasharatha. 'Demons are spoiling our prayers in the forest. Send Rama to protect us.'", "s": "palace|🧔@30,62,24;🤴@68,60,26"}, {"t": "The king was worried because Rama was still young. But he trusted the sage, and sent Rama and Lakshmana with him.", "s": "forest+sun|🧔@30,62,22;🤴@54,64,18;🧑@72,66,16"}, {"t": "On the way, Vishwamitra taught the princes special mantras. With them, they would never feel tired or hungry.", "s": "river+sun|🧔@32,62,22;🤴@58,66,16;🧑@74,68,14;✨@46,40,8"}, {"t": "At the forest ashram, the sages began their yajna. Then the demons Maricha and Subahu came flying, trying to ruin it.", "s": "forestN+moon|🔥@50,78,12;👹@30,30,14;👹@70,26,14;🤴@50,62,16"}, {"t": "Rama raised his bow. One arrow blew Maricha far away over the sea, and the other demons ran away. The yajna was finished in peace.", "s": "forest+sun|🤴@40,62,22;🏹@56,58,10;🔥@70,78,10"}, {"t": "The sages blessed Rama and Lakshmana. 'You have kept your promise to protect the good.'", "s": "forest+sun|🧔@30,60,20;🧔@70,60,20;🤴@50,66,16;🧑@62,68,12"}]}, {"id": "ram3", "title": "Rama Breaks Shiva's Bow", "group": "Ramayana", "age": 3, "source": "Valmiki's Ramayana, Bala Kanda", "series": "Ramayana", "ep": 3, "moral": "Real strength comes with humility and respect for teachers.", "talk": "Rama bowed to his teacher first. Why do you think he did that?", "pages": [{"t": "Vishwamitra took the princes to Mithila, the kingdom of King Janaka. Janaka had a daughter called Sita, who had been found as a baby in a field.", "s": "palace+sun|🤴@40,60,24;👸@66,62,20"}, {"t": "In his palace, Janaka kept an enormous bow that once belonged to Lord Shiva. It was so heavy that it was pulled on a cart by many men.", "s": "palace|🏹@50,66,40;🧑@20,78,10;🧑@80,78,10"}, {"t": "Janaka had promised: 'Sita will marry the one who can lift and string Shiva's bow.' Many strong kings had tried, and failed.", "s": "palace|🤴@30,60,20;🏹@62,74,30"}, {"t": "Rama bowed to his teacher, walked up, and lifted the bow as if it were a flower. Everyone gasped.", "s": "palace+sun|🤴@50,56,26;🏹@50,40,26"}, {"t": "He pulled the string, and the great bow broke in the middle with a sound like thunder! CRACK!", "s": "palace|🤴@50,60,24;⚡@50,30,14;🏹@50,44,22"}, {"t": "Sita placed a garland around Rama's neck. Rama and Sita were married, and all of Ayodhya and Mithila celebrated.", "s": "palace+sun|🤴@40,60,24;👸@62,60,24;💐@52,74,8;🎉@50,26,10"}]}, {"id": "ram4", "title": "Kaikeyi's Two Wishes", "group": "Ramayana", "age": 3, "source": "Valmiki's Ramayana, Ayodhya Kanda", "series": "Ramayana", "ep": 4, "moral": "Keeping a promise is important, even when it is hard.", "talk": "Have you ever kept a promise that was hard to keep?", "pages": [{"t": "King Dasharatha grew old. He decided, 'Rama will be the next king.' The whole city decorated their homes with flowers.", "s": "village+sun|🤴@50,58,26;💐@24,74,8;💐@76,74,8"}, {"t": "But Queen Kaikeyi's maid, Manthara, whispered, 'If Rama is king, your son Bharata will have nothing.' Kaikeyi began to worry.", "s": "palace|👸@36,60,24;👵@66,64,20"}, {"t": "Long ago, Kaikeyi had saved the king in a battle, and he had promised her two wishes. Now she asked for them.", "s": "palace|👸@36,60,24;🤴@66,60,24"}, {"t": "'First, make Bharata the king. Second, send Rama to live in the forest for fourteen years.' The king was heartbroken, but a promise is a promise.", "s": "palace|🤴@50,60,28;💧@58,46,5"}, {"t": "Rama was not angry at all. He smiled and said, 'I will keep my father's word.' He took off his royal clothes.", "s": "palace+sun|🤴@50,60,28;🙏@50,40,8"}, {"t": "Sita said, 'Where you go, I go.' Lakshmana said, 'I will protect you both.' The three walked away into the forest, and all of Ayodhya cried.", "s": "forest+sun|🤴@40,62,20;👸@56,64,18;🧑@72,64,16"}]}, {"id": "ram5", "title": "Bharata and the Sandals", "group": "Ramayana", "age": 3, "source": "Valmiki's Ramayana, Ayodhya Kanda", "series": "Ramayana", "ep": 5, "moral": "Love between brothers and sisters is more precious than any kingdom.", "talk": "How do you show love to your family?", "pages": [{"t": "King Dasharatha missed Rama so much that he grew ill and passed away. Bharata was called home from far away.", "s": "palace|👑@50,50,14;🪔@50,74,10"}, {"t": "When Bharata heard what had happened, he was upset. 'I do not want a kingdom taken from my brother!'", "s": "palace|🧑@50,62,26;😢@60,44,8"}, {"t": "He went to the forest with the people of Ayodhya to bring Rama back. He found Rama at Chitrakoot and fell at his feet.", "s": "forest+sun|🤴@60,62,24;🧑@36,72,18"}, {"t": "'Please come home and be our king,' Bharata begged. But Rama said gently, 'I must keep our father's promise for fourteen years.'", "s": "forest|🤴@60,60,24;🧑@36,66,18;🙏@36,50,6"}, {"t": "So Bharata asked for Rama's wooden sandals, his padukas. He carried them home on his head.", "s": "forest+sun|🧑@50,60,24;🩴@50,40,12"}, {"t": "Bharata placed the sandals on the throne and ruled for Rama, as his servant, waiting every day for his brother to return.", "s": "palace+sun|🩴@50,50,12;🧑@50,76,18"}]}, {"id": "ram6", "title": "The Golden Deer", "group": "Ramayana", "age": 5, "source": "Valmiki's Ramayana, Aranya Kanda", "series": "Ramayana", "ep": 6, "moral": "Things are not always what they seem. Brave hearts like Jatayu stand up for others.", "talk": "Why do you think Jatayu tried to stop Ravana?", "pages": [{"t": "Rama, Sita and Lakshmana built a little hut in the forest of Panchavati. One day, a beautiful golden deer with silver spots ran past.", "s": "forest+sun|🛖@24,62,18;🦌@66,70,18;✨@66,56,8"}, {"t": "'Rama, please catch that deer for me!' said Sita. Rama ran after it, and told Lakshmana to stay and guard Sita.", "s": "forest+sun|🤴@40,62,20;👸@64,64,18;🦌@88,70,12"}, {"t": "The deer was really the demon Maricha in disguise. When Rama's arrow hit him, he cried out in Rama's voice, 'Help, Lakshmana! Sita!'", "s": "forest|🦌@60,66,18;👹@60,46,12;🤴@30,62,18"}, {"t": "Sita was frightened and begged Lakshmana to go and help. At last, he went.", "s": "forest|👸@40,62,20;🧑@66,64,18"}, {"t": "Then an old holy man came to the hut asking for food. It was Ravana, the king of Lanka, in disguise. He took Sita away in his flying chariot.", "s": "forest+clouds|👹@50,40,22;👑@50,24,8;👸@60,50,12"}, {"t": "The brave old eagle Jatayu flew up to stop Ravana and fought him with all his strength, but he was hurt and fell.", "s": "mountain+clouds|🦅@40,40,22;👹@70,30,16"}, {"t": "Rama and Lakshmana came back to an empty hut. They found Jatayu, who told them, 'Ravana took Sita to the south.' Rama promised to find her.", "s": "forest|🤴@40,62,20;🧑@60,64,16;🦅@50,82,14"}]}, {"id": "ram7", "title": "Shabari and Hanuman", "group": "Ramayana", "age": 3, "source": "Valmiki's Ramayana, Aranya and Kishkindha Kanda", "series": "Ramayana", "ep": 7, "moral": "Love matters more than how grand a gift is. True friends help each other.", "talk": "Shabari gave fruits with love. What could you give someone with love?", "pages": [{"t": "Searching for Sita, Rama and Lakshmana reached the hut of an old woman called Shabari. She had waited for Rama for many years.", "s": "forest+sun|👵@56,62,22;🤴@30,62,20"}, {"t": "She washed their feet and gave them the best fruits she had gathered, with great love. Rama was very happy with her simple gift.", "s": "forest+sun|👵@56,64,20;🫐@44,80,8;🍎@54,82,8;🤴@30,62,20"}, {"t": "Shabari told them, 'Go to the hill of Rishyamuka. The monkey king Sugriva will help you.'", "s": "forest|👵@50,60,22;⛰️@80,40,14"}, {"t": "There they met a wise and strong monkey named Hanuman. When Hanuman saw Rama, he felt he had met his own Lord.", "s": "mountain+sun|🐒@60,66,22;🤴@32,62,20;💛@46,40,8"}, {"t": "Hanuman took them to Sugriva, and Rama and Sugriva became friends, promising to help each other.", "s": "mountain+sun|🐒@30,66,18;🐒@54,66,20;🤴@78,62,18;🔥@54,84,8"}, {"t": "The monkeys set out in all directions to find Sita. Rama gave Hanuman his ring. 'Show this to Sita, so she knows you come from me.'", "s": "mountain+sun|🤴@36,60,22;🐒@64,66,20;💍@50,46,8"}]}, {"id": "ram8", "title": "Hanuman's Great Leap", "group": "Ramayana", "age": 3, "source": "Valmiki's Ramayana, Sundara Kanda", "series": "Ramayana", "ep": 8, "moral": "Believe in yourself. You are stronger than you think.", "talk": "What can you do if you believe in yourself?", "pages": [{"t": "The monkeys reached the edge of the sea. Lanka was far away across the water. 'Who can jump so far?' they wondered.", "s": "sea+sun|🐒@30,70,14;🐒@50,72,14;🐒@70,70,14;🏝️@88,50,10"}, {"t": "Wise old Jambavan the bear said, 'Hanuman, you have great powers. You only need to remember them.' Hanuman grew bigger and bigger!", "s": "sea+sun|🐻@30,66,20;🐒@64,56,34"}, {"t": "With a mighty jump, Hanuman flew over the ocean, high over the waves, all the way to Lanka.", "s": "sea+clouds|🐒@50,36,22;🌊@50,80,20"}, {"t": "In a garden called Ashoka Vatika, under a tree, he found Sita, sad and waiting. Hanuman gave her Rama's ring. Sita's eyes filled with happy tears.", "s": "garden|🌳@60,36,36;👸@40,68,20;🐒@70,60,12;💍@54,62,6"}, {"t": "Ravana's soldiers caught Hanuman and set his tail on fire. But Hanuman jumped from roof to roof, and Lanka's palaces caught fire instead!", "s": "palace|🐒@50,40,20;🔥@24,60,14;🔥@76,58,14"}, {"t": "Hanuman dipped his tail in the sea and flew back to Rama. 'I have seen Sita! She is safe and waiting for you.'", "s": "mountain+sun|🐒@60,62,22;🤴@32,62,22;💛@46,40,8"}]}, {"id": "ram9", "title": "The Bridge to Lanka", "group": "Ramayana", "age": 5, "source": "Valmiki's Ramayana, Yuddha Kanda", "series": "Ramayana", "ep": 9, "moral": "Goodness wins in the end, and it is never too late to choose the right side.", "talk": "Vibhishana chose to do what was right. Was that easy?", "pages": [{"t": "Ravana's good brother Vibhishana told him, 'Return Sita to Rama.' Ravana refused, so Vibhishana left Lanka and joined Rama.", "s": "sea|👹@30,60,22;🧔@70,62,20"}, {"t": "To cross the sea, the monkey Nala led everyone to build a bridge of rocks and trees. The stones floated on the water, and the bridge was ready in five days.", "s": "sea+sun|🐒@30,60,18;🪨@50,72,10;🐒@70,60,18;🪨@78,76,10"}, {"t": "Rama's army crossed to Lanka. Rama sent Angada with a message: 'Return Sita, and there need be no war.' Ravana would not listen.", "s": "palace|🐒@36,64,18;👹@66,58,24;👑@66,40,8"}, {"t": "A great battle began. Ravana woke his giant brother Kumbhakarna, who slept for months, but Rama's army was brave and did not give up.", "s": "mountain+clouds|🐒@24,70,14;🐻@40,72,14;🐒@60,70,14;🤴@80,66,16"}, {"t": "When Lakshmana was badly hurt, Hanuman flew to the Himalayas for a healing herb. He could not find it, so he carried the whole mountain back! Lakshmana woke up.", "s": "mountain+clouds|🐒@50,50,22;⛰️@50,26,22;🧑@24,82,12"}, {"t": "At last, Rama and Ravana faced each other. After a long fight, Rama's arrow defeated Ravana, and the war was over.", "s": "skyN+stars|🤴@34,62,22;🏹@50,56,10;👹@74,62,18"}, {"t": "Rama made the good Vibhishana the new king of Lanka, and Sita was free at last.", "s": "palace+sun|🧔@50,60,24;👑@50,42,8;🤴@24,66,16;👸@78,66,16"}]}, {"id": "ram10", "title": "Rama Comes Home", "group": "Ramayana", "age": 3, "source": "Valmiki's Ramayana, Yuddha Kanda", "series": "Ramayana", "ep": 10, "moral": "Truth, love and patience bring us home in the end.", "talk": "What do you like most about Diwali?", "pages": [{"t": "Fourteen years were over. Rama, Sita, Lakshmana and their friends flew home in the flying chariot, the Pushpaka.", "s": "skyN+clouds+stars|🤴@40,46,16;👸@56,46,16;🧑@70,48,14;☁️@54,62,30"}, {"t": "Bharata had been waiting every single day. When he saw Rama, he ran to him, and the brothers hugged with tears of joy.", "s": "village+sun|🤴@40,60,24;🧑@60,62,22;💛@50,40,8"}, {"t": "Bharata placed Rama's sandals back on his feet. 'Your kingdom is waiting for you, brother.'", "s": "village+sun|🩴@50,78,10;🤴@50,54,24"}, {"t": "The people of Ayodhya decorated the city and lit lamps everywhere to welcome them home.", "s": "villageN+moon+stars|🪔@20,80,8;🪔@40,82,8;🪔@60,82,8;🪔@80,80,8;🏠@50,52,20"}, {"t": "Rama was crowned king, with Sita beside him. Hanuman sat at Rama's feet, happy to serve.", "s": "palace+sun|🤴@40,56,24;👸@62,56,22;🐒@52,80,12;👑@40,36,8"}, {"t": "Rama ruled with kindness and fairness, and the kingdom was happy. Today, many families light diyas at Diwali to remember the day Rama came home.", "s": "villageN+moon+stars|🪔@30,80,8;🪔@50,82,8;🪔@70,80,8;🎆@50,30,16"}]}, {"id": "mb1", "title": "Bhishma's Promise", "group": "Mahabharata", "age": 5, "source": "Vyasa's Mahabharata, Adi Parva", "series": "Mahabharata", "ep": 1, "moral": "A promise made from love can be very powerful.", "talk": "Why do you think Bhishma gave up being king?", "pages": [{"t": "King Shantanu of Hastinapur had a brave and wise son called Devavrata.", "s": "palace+sun|🤴@40,60,26;🧑@64,64,20"}, {"t": "The king wished to marry a fisherman's daughter, Satyavati. But her father said, 'Only if her children will be kings after you.'", "s": "river+sun|🤴@36,60,22;👩@58,62,18;🧔@78,62,18"}, {"t": "The king was sad, because Devavrata was meant to be the next king. Devavrata saw his father's sadness and went to the fisherman himself.", "s": "river|🧑@50,62,22;🧔@74,62,18"}, {"t": "Devavrata made a mighty promise: 'I will never be king, and I will never marry, so that Satyavati's children can rule.'", "s": "river+clouds|🧑@50,60,24;✋@50,40,10"}, {"t": "The gods were so amazed that flowers fell from the sky. From that day, he was called Bhishma, 'the one who made a terrible vow'.", "s": "river+sun|🧑@50,62,22;🌸@30,24,8;🌸@50,18,8;🌸@70,26,8"}, {"t": "His father blessed him: 'You will choose the time of your own death.' Bhishma kept his promise all his life, and protected Hastinapur for many years.", "s": "palace+sun|🤴@36,58,22;🧑@62,62,20;✨@50,36,10"}]}, {"id": "mb2", "title": "Arjuna and the Bird's Eye", "group": "Mahabharata", "age": 3, "source": "Vyasa's Mahabharata, Adi Parva", "series": "Mahabharata", "ep": 2, "moral": "When you focus on one thing at a time, you can do it well.", "talk": "What do you need to focus on today?", "pages": [{"t": "The five Pandava brothers, Yudhishthira, Bhima, Arjuna, Nakula and Sahadeva, and their cousins the hundred Kauravas, learned archery from their teacher, Guru Drona.", "s": "forest+sun|🧔@50,58,24;🧒@20,74,12;🧒@36,74,12;🧒@64,74,12;🧒@80,74,12"}, {"t": "One day, Drona placed a small wooden bird high on a tree. 'Aim at the bird's eye,' he said.", "s": "forest+sun|🌳@60,36,36;🐦@60,26,8;🧔@24,66,20"}, {"t": "He asked Yudhishthira, 'What do you see?' 'I see the tree, the leaves, the bird, and you, Guruji.' 'Put down your bow,' said Drona.", "s": "forest|🧔@26,64,20;🧒@54,70,16;🌳@80,36,24"}, {"t": "He asked many others. They all saw the sky, the branches, the leaves, and the bird.", "s": "forest|🧒@30,72,14;🧒@50,72,14;🧒@70,72,14;☁️@50,24,14"}, {"t": "Then he asked Arjuna. 'What do you see?' Arjuna said, 'I see only the bird's eye.'", "s": "forest+sun|🧒@40,70,18;🏹@54,64,10;👁️@70,30,10"}, {"t": "'Shoot!' said Drona. Arjuna's arrow hit the eye exactly. 'This is how you must focus,' Drona told everyone.", "s": "forest+sun|🌳@66,36,34;🐦@66,26,8;🏹@50,62,10;🧔@24,66,18"}]}, {"id": "mb3", "title": "The House of Lac", "group": "Mahabharata", "age": 5, "source": "Vyasa's Mahabharata, Adi Parva", "series": "Mahabharata", "ep": 3, "moral": "Listen to wise advice, and stay calm and together in danger.", "talk": "Who gives you wise advice?", "pages": [{"t": "Duryodhana, the eldest Kaurava, was jealous of the Pandavas. He built a beautiful house for them at Varanavata, made of lac and wax that burns very easily.", "s": "village|🏠@50,52,30;🤴@80,66,16;😠@80,50,6"}, {"t": "Their wise uncle Vidura sent them a secret warning in a puzzle: 'Fire cannot hurt a rat that lives in a hole.'", "s": "palace|🧔@40,60,22;📜@64,56,10"}, {"t": "Yudhishthira understood. A friend of Vidura's came secretly and dug a tunnel under the house.", "s": "homeN|🧑@50,70,18;⛏️@64,78,10;🕳️@50,86,12"}, {"t": "One night, when the house was set on fire, the Pandavas and their mother Kunti escaped quietly through the tunnel.", "s": "villageN+moon|🔥@50,48,26;🧑@24,82,10;🧑@36,84,10;👩@48,84,10"}, {"t": "Everyone thought they had died. But they were safe, hiding in the forest, dressed as simple travellers.", "s": "forestN+moon+stars|🧑@30,70,14;🧑@44,72,14;👩@58,72,14;🧑@72,70,14"}, {"t": "Brave Bhima carried his tired mother and brothers through the dark forest. The family stayed together and waited for the right time.", "s": "forestN+moon|🧑@50,64,26;👩@50,44,12"}]}, {"id": "mb4", "title": "The Fish Target", "group": "Mahabharata", "age": 5, "source": "Vyasa's Mahabharata, Adi Parva", "series": "Mahabharata", "ep": 4, "moral": "Practice and patience help us do difficult things.", "talk": "What is something hard that you are practising?", "pages": [{"t": "King Drupada of Panchala had a daughter, Draupadi. He set a very hard test for her marriage.", "s": "palace+sun|🤴@40,60,24;👸@64,62,22"}, {"t": "High above, a target in the shape of a fish was spinning. The archer had to string a huge bow and hit the fish's eye.", "s": "palace|🐟@50,24,14;🌀@50,24,20;🏹@50,74,24"}, {"t": "Kings and princes from everywhere tried. Some could not even lift the bow!", "s": "palace|🤴@26,66,16;🤴@50,68,16;🤴@74,66,16;😓@50,48,8"}, {"t": "Then a young man dressed as a simple brahmin stood up. It was Arjuna, in disguise.", "s": "palace|🧑@50,62,24;🏹@64,62,12"}, {"t": "He strung the bow easily, aimed carefully, and shot five arrows. The fish target fell!", "s": "palace+sun|🧑@40,66,22;🏹@54,60,10;🐟@70,30,12"}, {"t": "Draupadi garlanded Arjuna. Everyone was surprised to find that the Pandavas were alive after all!", "s": "palace+sun|🧑@40,62,22;👸@60,62,22;💐@50,74,8;🎉@50,26,10"}]}, {"id": "mb5", "title": "The Yaksha's Questions", "group": "Mahabharata", "age": 5, "source": "Vyasa's Mahabharata, Vana Parva", "series": "Mahabharata", "ep": 5, "moral": "Listen before you act. Being fair and wise is the greatest strength.", "talk": "Yudhishthira chose Nakula to be fair. What does fair mean to you?", "pages": [{"t": "During their years in the forest, the Pandavas became very thirsty. Nakula went to find water and found a clear lake.", "s": "pond+sun|🧑@50,62,20;💧@60,80,8"}, {"t": "A crane on the lake said, 'This lake is mine. Answer my questions before you drink.' Nakula did not listen, drank, and fell down asleep.", "s": "pond|🦢@70,62,16;🧑@36,78,14;💤@40,66,6"}, {"t": "Sahadeva, Arjuna and Bhima came one by one. Each one drank without answering, and each one fell down.", "s": "pond|🧑@24,80,12;🧑@40,82,12;🧑@58,82,12;🦢@78,62,14"}, {"t": "Then Yudhishthira came. He bowed and said, 'Please ask your questions.' The crane became a Yaksha, a spirit.", "s": "pond|🤴@40,62,22;✨@70,48,18"}, {"t": "'What is faster than the wind?' 'The mind.' 'What is the greatest wonder?' 'Every day people see others pass away, yet live as if they will live forever.' Yudhishthira answered every question wisely.", "s": "pond+stars|🤴@40,62,22;💭@64,40,14"}, {"t": "'I will bring back one brother. Choose.' Yudhishthira chose Nakula. 'My mother Kunti has me. Let my other mother Madri also have a son.'", "s": "pond|🤴@40,62,22;🧑@66,78,14"}, {"t": "The Yaksha was really Dharma, the god of goodness. Pleased by his fairness, he brought all the brothers back to life.", "s": "pond+sun|✨@50,30,20;🧑@20,72,12;🧑@36,74,12;🤴@52,70,14;🧑@68,74,12;🧑@84,72,12"}]}, {"id": "mb6", "title": "The Game of Dice", "group": "Mahabharata", "age": 5, "source": "Vyasa's Mahabharata, Sabha Parva", "series": "Mahabharata", "ep": 6, "moral": "Games of greed lead to trouble. Faith gives strength in hard times.", "talk": "Why is it wrong to cheat in a game?", "pages": [{"t": "Yudhishthira became king of Indraprastha, a wonderful city. Duryodhana was jealous and planned a trick with his uncle Shakuni.", "s": "palace+sun|🤴@40,60,22;🤴@70,64,18;😠@70,46,6"}, {"t": "They invited Yudhishthira to a game of dice. Shakuni's dice were tricky and always won.", "s": "court|🎲@50,74,10;🤴@30,62,18;🧔@70,62,18"}, {"t": "Yudhishthira kept playing and kept losing: his gold, his kingdom, his brothers, himself, and even Draupadi.", "s": "court|🤴@40,62,20;😟@40,46,6;🎲@60,76,8"}, {"t": "Duryodhana's brother Dushasana dragged Draupadi into the court and tried to pull away her saree. Draupadi prayed to Krishna with all her heart.", "s": "court|👸@50,60,22;🙏@50,42,8"}, {"t": "A miracle happened! The saree became longer and longer, with no end, until Dushasana grew tired and gave up.", "s": "court|👸@50,58,22;🌈@50,30,30;✨@70,40,10"}, {"t": "The elders were ashamed. The Pandavas had to leave for twelve years in the forest and one year in hiding. They left with Draupadi, quiet but strong.", "s": "forest|🧑@24,66,14;🧑@38,68,14;🤴@52,66,14;👸@66,68,14;🧑@80,66,14"}]}, {"id": "mb7", "title": "Krishna, the Messenger of Peace", "group": "Mahabharata", "age": 5, "source": "Vyasa's Mahabharata, Udyoga Parva", "series": "Mahabharata", "ep": 7, "moral": "Always try for peace first. Pride and greed close the door to peace.", "talk": "How do you make peace after a fight with a friend?", "pages": [{"t": "The thirteen years were over. The Pandavas asked for their kingdom back, but Duryodhana refused.", "s": "palace|🤴@60,60,24;😠@60,42,6;🧑@28,66,16"}, {"t": "Krishna wanted to stop a war. He went to Hastinapur himself, as a messenger of peace.", "s": "village+sun|🤴@50,60,24;🪶@54,40,6;🐎@20,70,14"}, {"t": "In the Kaurava court, Krishna said, 'Give the Pandavas just five villages, and there will be peace.'", "s": "court|🤴@50,58,24;🪶@54,40,6;🖐️@70,46,8"}, {"t": "But Duryodhana said, 'I will not give them even as much land as the point of a needle!'", "s": "court|🤴@60,60,24;😠@60,42,8;📍@36,46,8"}, {"t": "The wise elders, Bhishma and Vidura, begged Duryodhana to listen, but he would not. He even tried to capture Krishna.", "s": "court|👴@30,62,18;🧔@50,62,18;🤴@74,62,18"}, {"t": "Krishna showed his shining divine form, and the whole court was dazzled. He left calmly. Now there would have to be a war.", "s": "court|✨@50,40,34;🤴@50,62,20"}]}, {"id": "mb8", "title": "Arjuna Chooses Krishna", "group": "Mahabharata", "age": 5, "source": "Vyasa's Mahabharata, Udyoga Parva", "series": "Mahabharata", "ep": 8, "moral": "Choose wisdom and true friendship over size and power.", "talk": "Would you choose a big army or a wise friend? Why?", "pages": [{"t": "Before the war, both Arjuna and Duryodhana went to Krishna in Dwarka to ask for his help.", "s": "palace+sun|🤴@50,60,24;🪶@54,40,6"}, {"t": "Krishna was asleep. Duryodhana sat proudly near his head. Arjuna stood humbly near his feet.", "s": "homeN|🛏️@50,74,40;🤴@50,66,16;🤴@20,60,14;🧑@84,62,14"}, {"t": "When Krishna woke up, he saw Arjuna first. 'I will give you a choice,' he said.", "s": "home+sun|🤴@50,58,22;🪶@54,42,6;🧑@80,64,16;🤴@20,62,16"}, {"t": "'One of you can have my huge army. The other can have me alone, and I will not fight in the war.'", "s": "home|🤴@50,58,22;🐎@20,80,10;🐎@30,82,10;🐘@80,80,12"}, {"t": "Arjuna chose at once: 'I want you, Krishna.' Duryodhana was happy to get the big army.", "s": "home+sun|🧑@36,62,20;🤴@62,58,22;💛@50,40,8"}, {"t": "Krishna became Arjuna's charioteer and guide. Arjuna knew that wisdom and a true friend are worth more than any army.", "s": "field+sun|🐎@36,64,18;☸️@52,76,10;🤴@54,52,14;🧑@68,54,14"}]}, {"id": "mb9", "title": "The Song on the Battlefield", "group": "Mahabharata", "age": 5, "source": "Vyasa's Mahabharata, Bhishma Parva (the Bhagavad Gita)", "series": "Mahabharata", "ep": 9, "moral": "Do your duty with courage, and do your best without worrying about the result.", "talk": "When did you feel scared but still did the right thing?", "pages": [{"t": "On the field of Kurukshetra, two huge armies stood face to face. Arjuna said, 'Krishna, take my chariot between the armies. I want to see.'", "s": "field+sun|🐎@40,66,18;☸️@52,78,10;🧑@58,54,14;🤴@40,54,14"}, {"t": "Arjuna looked across and saw his grandfather Bhishma, his teacher Drona, his cousins and friends. His hands shook. He put down his bow.", "s": "field|🧑@50,60,24;🏹@50,82,14;😢@58,44,6"}, {"t": "'I cannot fight my own family,' he cried. Krishna smiled kindly and began to teach him. These teachings are called the Bhagavad Gita, the Song of God.", "s": "field|🤴@36,58,22;🧑@64,62,20;📜@50,36,10"}, {"t": "Krishna said, 'Do your duty with a calm mind. The soul is never born and never dies. Do your best, and do not worry about the result.'", "s": "field+sun|🤴@40,58,24;🪶@44,38,6;🧑@68,64,18"}, {"t": "Then Krishna showed Arjuna his universal form: the whole universe, with its suns and stars, shining inside him.", "s": "skyN+stars|✨@50,40,40;🌞@30,30,10;🌙@70,26,10"}, {"t": "Arjuna's fear went away. 'My doubts are gone,' he said, and he picked up his bow to stand for what was right.", "s": "field+sun|🧑@50,58,24;🏹@64,56,12;🤴@24,62,18"}]}, {"id": "mb10", "title": "After the Great War", "group": "Mahabharata", "age": 5, "source": "Vyasa's Mahabharata, Bhishma to Shanti Parva", "series": "Mahabharata", "ep": 10, "moral": "War brings sorrow to everyone. Peace and fairness are the greatest gifts.", "talk": "Why is peace better than fighting?", "pages": [{"t": "The war of Kurukshetra lasted eighteen days. Many brave warriors fought, and many did not come home.", "s": "field+clouds|🐎@30,70,14;🐎@70,70,14;🏹@50,60,10"}, {"t": "Young Abhimanyu, Arjuna's son, went bravely into a difficult battle formation called the chakravyuha. He fought with great courage until the very end.", "s": "field|🧒@50,62,20;☸️@50,82,12;🌀@50,30,20"}, {"t": "Grandfather Bhishma fell in battle and lay on a bed of arrows. He waited for the right time to leave this world, as was his blessing.", "s": "fieldN+moon|👴@50,70,22;🏹@30,82,8;🏹@70,82,8"}, {"t": "The Pandavas won the war, but they were not happy. They had lost so many people they loved. Yudhishthira cried.", "s": "field|🤴@50,62,24;😢@58,44,8"}, {"t": "From his bed of arrows, Bhishma taught Yudhishthira how to be a good king: be fair, protect the weak, and care for every person.", "s": "field+sun|👴@36,72,20;🤴@64,62,22;📜@50,40,8"}, {"t": "Yudhishthira ruled kindly for many years. The Pandavas learned that in a war, even the winners lose something, and peace is the greatest gift.", "s": "palace+sun|🤴@50,58,26;🕊️@50,30,12"}]}, {"id": "gita1", "title": "Do Your Best", "group": "Gita", "age": 5, "source": "Bhagavad Gita 2.47", "series": "Gita", "ep": 1, "moral": "Do your best, and let go of worrying about the result.", "talk": "What will you do your best at tomorrow?", "pages": [{"t": "On the battlefield, Krishna told Arjuna something very important. It is one of the most famous lines of the Gita.", "s": "field+sun|🤴@36,58,22;🪶@40,38,6;🧑@64,62,20"}, {"t": "Little Meera was practising for a running race. Every morning she ran, even when her legs felt tired.", "s": "field+sun|👧@50,64,20;🏃@70,66,12"}, {"t": "On race day, she ran her very best. She came third, not first. 'All that practice, for nothing!' she cried.", "s": "field|👧@50,64,20;🥉@64,46,8;😢@44,46,6"}, {"t": "Krishna said: you have a right to do your work, but not to the result. Do not work only for the prize, and do not stop working either.", "s": "field|📜@50,40,18", "sh": "कर्मण्येवाधिकारस्ते मा फलेषु कदाचन। मा कर्मफलहेतुर्भूर्मा ते सङ्गोऽस्त्वकर्मणि॥"}, {"t": "Meera's grandmother said, 'You ran faster than ever before. That is your real win.' Meera smiled, and kept practising for the joy of running.", "s": "field+sun|👵@36,62,22;👧@62,66,18;💛@50,40,8"}]}, {"id": "gita2", "title": "Happy Days and Sad Days", "group": "Gita", "age": 5, "source": "Bhagavad Gita 2.14", "series": "Gita", "ep": 2, "moral": "Feelings come and go. Be patient and calm.", "talk": "What helps you feel better when you are sad?", "pages": [{"t": "Arjuna felt very sad on the battlefield. Krishna told him that happy and sad feelings come and go, like the seasons.", "s": "field|🤴@36,58,22;🧑@64,62,20"}, {"t": "In summer it is hot, and in winter it is cold. But summer does not stay forever, and winter does not stay forever.", "s": "field+sun|☀️@30,30,16;❄️@70,30,16"}, {"t": "Krishna said: cold and heat, happiness and sadness, come and go. They do not last. Bear them patiently, Arjuna.", "s": "skyN+stars|📜@50,40,18", "sh": "मात्रास्पर्शास्तु कौन्तेय शीतोष्णसुखदुःखदाः। आगमापायिनोऽनित्यास्तांस्तितिक्षस्व भारत॥"}, {"t": "When Aarav's toy broke, he felt sad all evening. But the next morning, the sun came out, and he built a new toy with his father.", "s": "home+sun|🧒@40,66,20;👨@64,60,24;🧸@52,82,8"}, {"t": "Feelings are like clouds passing in the sky. We can feel them, and wait calmly for them to pass.", "s": "field+clouds+sun|☁️@40,30,20;😊@70,60,12"}]}, {"id": "gita3", "title": "Be Your Own Best Friend", "group": "Gita", "age": 5, "source": "Bhagavad Gita 6.5", "series": "Gita", "ep": 3, "moral": "Speak kindly to yourself. Say 'not yet' instead of 'never'.", "talk": "What kind words can you say to yourself when something is hard?", "pages": [{"t": "Krishna taught Arjuna that our own mind can be our best friend, or it can make things hard for us.", "s": "field+sun|🤴@36,58,22;🧑@64,62,20"}, {"t": "Kabir could not tie his shoelaces. 'I am bad at this. I can never do it,' he said, and threw his shoe.", "s": "home|🧒@44,66,20;👟@70,78,10;😠@50,48,6"}, {"t": "Krishna said: lift yourself up with your own mind, and do not pull yourself down. Your mind is your friend, and it can also be your enemy.", "s": "skyN+stars|📜@50,40,18", "sh": "उद्धरेदात्मनात्मानं नात्मानमवसादयेत्। आत्मैव ह्यात्मनो बन्धुरात्मैव रिपुरात्मनः॥"}, {"t": "Kabir took a deep breath and said to himself, 'I cannot do it yet. I will try once more.'", "s": "home|🧒@44,66,20;💭@60,46,10"}, {"t": "He tried again, and again, and on the fifth try, he tied a bow! 'I did it!' His kind words to himself had helped.", "s": "home+sun|🧒@44,66,20;👟@60,80,10;🎉@60,40,10"}]}, {"id": "gita4", "title": "Whenever Goodness Needs Help", "group": "Gita", "age": 5, "source": "Bhagavad Gita 4.7", "series": "Gita", "ep": 4, "moral": "Goodness always finds a way. You can be a helper of goodness too.", "talk": "How can you help when someone is being unkind?", "pages": [{"t": "Krishna told Arjuna a promise, a promise that gives hope to people everywhere.", "s": "field+sun|🤴@36,58,22;🧑@64,62,20"}, {"t": "Krishna said: whenever goodness becomes weak and wrongdoing grows strong, I come to the world to help.", "s": "skyN+stars|📜@50,40,18", "sh": "यदा यदा हि धर्मस्य ग्लानिर्भवति भारत। अभ्युत्थानमधर्मस्य तदात्मानं सृजाम्यहम्॥"}, {"t": "That is why, in the stories, Rama came to protect the good from Ravana, and Krishna came to help the Pandavas.", "s": "palace+sun|🤴@36,60,22;🏹@50,60,8;🤴@66,60,22;🪶@70,42,6"}, {"t": "Goodness also needs little helpers like you. When you see someone being unkind, you can stand up, and you can tell a grown-up.", "s": "school+sun|🧒@36,66,18;👧@58,66,18;🙋@36,48,6"}, {"t": "Every time you choose kindness and truth, you help goodness grow strong in the world.", "s": "garden+sun|🧒@40,66,18;👧@60,66,18;🌱@50,84,10;💛@50,40,8"}]}, {"id": "gita5", "title": "A Leaf, a Flower, a Fruit", "group": "Gita", "age": 3, "source": "Bhagavad Gita 9.26", "series": "Gita", "ep": 5, "moral": "What matters most in a gift is the love behind it.", "talk": "What simple gift could you make with love?", "pages": [{"t": "Krishna told Arjuna that God does not want big or costly gifts. He only wants love.", "s": "field+sun|🤴@36,58,22;🧑@64,62,20"}, {"t": "Krishna said: if someone offers me a leaf, a flower, a fruit or a little water, with love, I happily accept it.", "s": "garden+sun|🍃@30,50,10;🌸@44,50,10;🍎@58,50,10;💧@72,50,10", "sh": "पत्रं पुष्पं फलं तोयं यो मे भक्त्या प्रयच्छति। तदहं भक्त्युपहृतमश्नामि प्रयतात्मनः॥"}, {"t": "Remember Shabari, who gave Rama simple fruits, and Sudama, who gave Krishna a little poha? Their gifts were small, but full of love.", "s": "forest+sun|👵@36,64,20;🫐@36,82,8;🧔@66,64,20;🍚@66,82,8"}, {"t": "Little Riya had no money for her mother's birthday. She picked a flower and drew a card with a big heart.", "s": "garden+sun|👧@40,66,20;🌼@58,70,10;💌@70,60,10"}, {"t": "Her mother hugged her tightly. 'This is the best gift I have ever had.' Love makes every gift special.", "s": "home+sun|👩@44,58,26;👧@62,66,18;💛@52,36,10"}]}, {"id": "gita6", "title": "A Friend to Everyone", "group": "Gita", "age": 5, "source": "Bhagavad Gita 12.13", "series": "Gita", "ep": 6, "moral": "Be a friend to all living beings. Be kind, humble and forgiving.", "talk": "Who can you be extra kind to tomorrow?", "pages": [{"t": "Arjuna asked Krishna, 'Who is the person you love most?' Krishna told him about a kind and gentle heart.", "s": "field+sun|🤴@36,58,22;🧑@64,62,20"}, {"t": "Krishna said: the one who hates no living being, who is friendly and kind to all, who is not proud, stays calm in joy and sorrow, and forgives, is dear to me.", "s": "skyN+stars|📜@50,40,18", "sh": "अद्वेष्टा सर्वभूतानां मैत्रः करुण एव च। निर्ममो निरहङ्कारः समदुःखसुखः क्षमी॥"}, {"t": "At school, a new boy sat alone at lunch. Some children laughed at his tiffin. Isha sat next to him and shared her parathas.", "s": "school+sun|🧒@64,66,18;👧@40,66,18;🍱@52,82,10"}, {"t": "On the way home, Isha filled a bowl of water for a thirsty street dog, and gave grains to the sparrows.", "s": "village+sun|👧@40,66,18;🐕@62,76,14;🥣@54,84,8;🐦@76,60,8"}, {"t": "Being kind to every living being, people, animals and birds, makes the world a happier place.", "s": "garden+sun|👧@40,66,18;🧒@60,66,18;🐕@26,80,10;🐦@76,50,8;💛@50,36,10"}]}];